  const qIdx = rest.indexOf('?')
  if (qIdx !== -1) {
    query = rest.slice(qIdx + 1)
    rest = rest.slice(0, qIdx)
  }

  let scheme
  const colonIdx = rest.indexOf(':')
  if (colonIdx !== -1 && !rest.slice(0, colonIdx).includes('/')) {
    scheme = rest.slice(0, colonIdx)
    rest = rest.slice(colonIdx + 1)
  }

